import json,os
def transform(grid):
    import collections
    g=[row[:] for row in grid]; h=len(g); w=len(g[0])
    cnt=collections.Counter(v for row in g for v in row)
    bg=cnt.most_common(1)[0][0]
    info={}
    for r,row in enumerate(g):
        runs=[];c=0
        while c<w:
            if row[c]!=bg:
                v=row[c];s=c
                while c<w and row[c]==v: c+=1
                runs.append((v,s,c-1))
            else: c+=1
        if len(runs)==1: info.setdefault(runs[0][0],[]).append((r,runs[0][1],runs[0][2]))
    for v,lst in info.items():
        if len(lst)>=2:
            E=max(e for _,_,e in lst)
            for r,s,e in lst:
                if e<E:
                    for c in range(e+1,E+1): g[r][c]=1
    return g
